fn p0(content:&Content,field:&str,gate:bool)->usize{match content{Content::Source(e)=>0,Content::ShowRecipe(e)=>1,Content::Located(e)=>2,Content::Realized(e)=>3,Content::Empty=>4,Content::Parbreak=>5,Content::Par { body }=>6,Content::PageRun(e)=>7,Content::Sequence(v)=>8,Content::Label(e)=>9,Content::Figure(e)=>10,Content::FigureCaption(e)=>11,Content::Grid(e)=>12,Content::GridHeader(e)=>13,Content::GridFooter(e)=>14,Content::GridCell(e)=>15,Content::GridHLine(_) | Content::GridVLine(_)=>16,Content::TableHLine(_) | Content::TableVLine(_)=>17,Content::Table(e)=>18,Content::TableCell(e)=>19,Content::TableHeader(e)=>20,Content::TableFooter(e)=>21,Content::Bibliography(e)=>22,Content::Cite(e)=>23,Content::Footnote(e)=>24,Content::FootnoteEntry(e)=>25,Content::Divider(d)=>26,Content::Terms(e)=>27,Content::TermItem(e)=>28,Content::Quote(e)=>29,Content::Document { .. }=>30,Content::Asset { .. }=>31,Content::Underline(e)=>32,Content::Strike(e)=>33,Content::Overline(e)=>34,Content::SmallCaps { body }=>35,Content::SmartQuote(e)=>36,Content::PdfAttach(e)=>37,Content::PdfArtifact(e)=>38,Content::Pad(e)=>39,Content::Hide(e)=>40,Content::HSpace(e)=>41,Content::VSpace(e)=>42,Content::Pagebreak(e)=>43,Content::Colbreak(e)=>44,Content::Block(e)=>45,Content::Boxed(e)=>46,Content::Stack(e)=>47,Content::Repeat(e)=>48,Content::Columns(e)=>49,Content::Dynamic(e)=>50,Content::Styled(styled)=>51,Content::Strong(e)=>52,Content::Emph(e)=>53,Content::MathLimitsOverride(e)=>54,_=>9999,}}
fn p1(content:&Content,field:&str,gate:bool)->usize{match content{Content::Equation(e)=>0,Content::Styled(styled)=>1,_=>9999,}}
fn p2(content:&Content,field:&str,gate:bool)->usize{match (content,field){(Content::Source(e), f)=>0,(Content::ShowRecipe(e), f)=>1,(Content::Located(e), f)=>2,(Content::Realized(e), f)=>3,(Content::Heading(h), f)=>4,(Content::Raw(e), f)=>5,(Content::Transform(e), f)=>6,(Content::OutlineEntry(e), f)=>7,(Content::Title(t), f)=>8,(Content::Strong(e), f)=>9,(Content::Emph(e), f)=>10,(Content::Linebreak(e), f)=>11,(Content::SmartQuote(e), "double")=>12,(Content::SmartQuote(e), "enabled")=>13,(Content::SmartQuote(e), "alternative")=>14,(Content::SmartQuote(e), "quotes")=>15,(Content::Figure(e), f)=>16,(Content::FigureCaption(e), f)=>17,(Content::Equation(e), f)=>18,(Content::MathMatrix(e), f)=>19,(Content::TableCell(e), f)=>20,(Content::MathPrimes(e), f)=>21,(Content::MathLr(e), f)=>22,(Content::MathUnderbrace(e), f)=>23,(Content::MathUnderbracket(e), f)=>24,(Content::MathUnderparen(e), f)=>25,(Content::MathUndershell(e), f)=>26,(Content::MathStretch(e), f)=>27,(Content::PdfArtifact(e), f)=>28,(Content::Styled(styled), f) if gate=>29,(Content::SmallCaps { body }, "body")=>30,(Content::Par { body }, "body")=>31,(Content::Dynamic(e), f)=>32,(Content::Metadata(e), "value")=>33,_=>9999,}}
fn p3(content:&Content,field:&str,gate:bool)->usize{match content{Content::Source(e)=>0,Content::ShowRecipe(e)=>1,Content::Located(e)=>2,Content::Realized(e)=>3,Content::TableCell(e)=>4,Content::Table(e)=>5,Content::Text(s)=>6,Content::SpaceFromNewline=>7,Content::Styled(styled) if gate=>8,_=>9999,}}
fn p4(content:&Content,field:&str,gate:bool)->usize{match content{Content::Source(e)=>0,Content::ShowRecipe(e)=>1,Content::Located(e)=>2,Content::Realized(e)=>3,Content::MathCases(elem)=>4,Content::MathMatrix(elem)=>5,_=>9999,}}
fn p5(content:&Content,field:&str,gate:bool)->usize{match content{Content::Source(e)=>0,Content::TableCell(e)=>1,Content::Table(e)=>2,_=>9999,}}
